// PrivateNFTTransfer: 5 public inputs [oldNftHash, newNftHash, nftId, collectionAddress, nullifier]
interface INFTTransferVerifier {
    function verifyProof(
        uint256[2] memory a,
        uint256[2][2] memory b,
        uint256[2] memory c,
        uint256[5] memory input
    ) external view returns (bool);
}

// GamingItemTrade: 5 public inputs [oldItemHash, newItemHash, paymentNoteHash, gameId, nullifier]
interface IGamingItemTradeVerifier {
    function verifyProof(
        uint256[2] memory a,
        uint256[2][2] memory b,
        uint256[2] memory c,
        uint256[5] memory input
    ) external view returns (bool);
}

// LootBoxOpen: 5 public inputs [boxCommitment, outcomeCommitment, vrfOutput, boxId, nullifier]
interface ILootBoxVerifier {
    function verifyProof(
        uint256[2] memory a,
        uint256[2][2] memory b,
        uint256[2] memory c,
        uint256[5] memory input
    ) external view returns (bool);
}

// CardDraw: 5 public inputs [deckCommitment, drawCommitment, drawIndex, gameId, playerCommitment]
interface ICardDrawVerifier {
    function verifyProof(
        uint256[2] memory a,
        uint256[2][2] memory b,
        uint256[2] memory c,
        uint256[5] memory input
    ) external view returns (bool);
}

